let SKINS = [];
const SKINS_LOCAL = "skins-data.json";

function normalizeCatalogRow(s) {
  if (!s) return null;
  const name = String(s.name || "").trim();
  if (!name || name.length < 2) return null;
  const id = String(s.id || "").trim();
  if (!id) return null;
  const image = String(s.image || "").trim();
  const fb = Array.isArray(s.fb) ? s.fb.slice() : (Array.isArray(s.imageFallbacks) ? s.imageFallbacks.slice() : []);
  if (!image && !fb.length) return null;
  return {
    id,
    name: name.slice(0, 56),
    image: image || fb[0],
    imageFallbacks: image ? fb : fb.slice(1),
    category: s.cat || s.category || "lainnya",
    rare: s.r || s.rare || ""
  };
}

function applySkinsList(list, { merge } = {}) {
  const out = [];
  const seenId = new Set();
  const seenName = new Set();
  const source = (merge && SKINS.length) ? SKINS.concat(list || []) : (list || []);
  for (const raw of source) {
    const s = normalizeCatalogRow(raw);
    if (!s) continue;
    if (seenId.has(s.id)) continue;
    const nk = String(s.name || "").toLowerCase().replace(/\s+/g, " ").trim();
    if (nk && seenName.has(nk)) continue;
    seenId.add(s.id);
    if (nk) seenName.add(nk);
    out.push(s);
  }
  SKINS = out;
  return out;
}

/** Seed instan (1300+) lalu load paralel per kategori */
async function loadAllSkinsFromItemID2() {
  const grid = document.getElementById("skinGrid");

  // 1) INSTAN — ribuan seed tanpa network
  if (Array.isArray(SKINS_SEED) && SKINS_SEED.length) {
    applySkinsList(SKINS_SEED, { merge: false });
    if (typeof renderCategoryTabs === "function") renderCategoryTabs();
    if (typeof renderSkins === "function") renderSkins();
    console.info("[skins] seed", SKINS.length);
  } else if (grid) {
    grid.innerHTML = '<div class="skin-empty">Memuat skin…</div>';
  }

  // 2) Paralel: file per kategori (lebih andal dari 1 file besar)
  const parts = [
    "skins-senjata.json",
    "skins-baju.json",
    "skins-bundle.json",
    "skins-avatar.json",
    "skins-lainnya.json",
    "skins-data.json"
  ];
  const collected = [];
  await Promise.all(
    parts.map(async (file) => {
      try {
        const res = await fetch(file + "?v=3", { cache: "default" });
        if (!res.ok) return;
        const data = await res.json();
        if (Array.isArray(data) && data.length) {
          collected.push(...data);
        }
      } catch (e) {}
    })
  );

  if (collected.length) {
    applySkinsList(collected, { merge: false });
    if (typeof renderCategoryTabs === "function") renderCategoryTabs();
    if (typeof renderSkins === "function") renderSkins();
    console.info("[skins] full", SKINS.length);
  } else if (!SKINS.length && grid) {
    grid.innerHTML = '<div class="skin-empty">Upload file skins-*.json ke folder web, lalu refresh.</div>';
  }
  return SKINS;
}

