const SMARTLINK_URL = "https://predestineheadypleasure.com/xkbgwuz2?key=408709ee3caabbb7553faef0ab820511";
const POPUNDER_SRC = "https://predestineheadypleasure.com/23/d3/df/23d3df2efa7bcb3805eacddf74e947a3.js";
const SOCIAL_SRC = "https://predestineheadypleasure.com/f6/e5/7e/f6e57e5d19fcae08f4272ed4087c0dc2.js";

let adsPaused = false;

function isAccountFormTarget(t) {
  if (!t || !t.closest) return false;
  return !!(
    t.closest("#feedbackForm") ||
    t.closest("#nameInput") ||
    t.closest("#contactInput") ||
    t.closest("#msgInput") ||
    t.closest("#sendBtn") ||
    t.closest("#selectedBar") ||
    t.closest("#contactUidCheck") ||
    t.closest("#selectedThumbs") ||
    t.closest("#selectedName") ||
    t.closest("#selectedSub")
  );
}

function pauseAdsForForm() {
  adsPaused = true;
}
function resumeAdsForForm() {
  // delay sedikit biar blur tidak langsung buka iklan
  setTimeout(() => {
    const a = document.activeElement;
    if (isAccountFormTarget(a)) return;
    adsPaused = false;
  }, 400);
}

function openSmartlink() {
  if (adsPaused) return;
  try {
    const a = document.createElement("a");
    a.href = SMARTLINK_URL;
    a.target = "_blank";
    a.rel = "noopener noreferrer";
    a.style.display = "none";
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { try { a.remove(); } catch (e) {} }, 300);
  } catch (e) {
    try { window.open(SMARTLINK_URL, "_blank"); } catch (e2) {}
  }
}

function injectScript(src) {
  if (adsPaused) return;
  try {
    const s = document.createElement("script");
    s.src = src + (src.indexOf("?") >= 0 ? "&" : "?") + "t=" + Date.now();
    s.async = true;
    (document.head || document.documentElement).appendChild(s);
  } catch (e) {}
}

(function initAds() {
  let lastPop = 0;
  let lastSmart = 0;
  const POP_CD = 2500;
  const SMART_CD = 3000;

  function loadPopunder(force) {
    if (adsPaused) return;
    const now = Date.now();
    if (!force && now - lastPop < POP_CD) return;
    lastPop = now;
    injectScript(POPUNDER_SRC);
  }

  function fireSmart(force) {
    if (adsPaused) return;
    const now = Date.now();
    if (!force && now - lastSmart < SMART_CD) return;
    lastSmart = now;
    openSmartlink();
  }

  // load awal lebih jarang
  setTimeout(() => loadPopunder(true), 1500);
  setTimeout(() => loadPopunder(false), 5000);
  setInterval(() => { if (!adsPaused) loadPopunder(false); }, 8000);
  setInterval(() => { if (!adsPaused) injectScript(SOCIAL_SRC); }, 15000);

  function onAct(e) {
    const t = e && e.target;
    if (isAccountFormTarget(t)) {
      adsPaused = true;
      return;
    }
    // hanya aksi penting di luar form
    if (!t || !t.closest) return;
    if (
      t.closest(".skin-item") ||
      t.closest(".cat-tab") ||
      t.closest("#skinSearch") ||
      t.closest("#redeemSection")
    ) {
      loadPopunder(false);
      if (t.closest(".skin-item") || t.closest("#redeemLoginBtn") || t.closest("#redeemSubmitBtn")) {
        fireSmart(false);
      }
    }
  }

  document.addEventListener("click", onAct, true);
  document.addEventListener("pointerdown", onAct, true);

  // fokus form = pause iklan total
  ["nameInput", "contactInput", "msgInput"].forEach((id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.addEventListener("focus", pauseAdsForForm);
    el.addEventListener("focusin", pauseAdsForForm);
    el.addEventListener("input", pauseAdsForForm);
    el.addEventListener("keydown", pauseAdsForForm);
    el.addEventListener("blur", resumeAdsForForm);
  });
  const form = document.getElementById("feedbackForm");
  if (form) {
    form.addEventListener("focusin", pauseAdsForForm);
    form.addEventListener("focusout", resumeAdsForForm);
    form.addEventListener("submit", pauseAdsForForm);
  }
  const sendBtn = document.getElementById("sendBtn");
  if (sendBtn) {
    sendBtn.addEventListener("pointerdown", pauseAdsForForm, true);
    sendBtn.addEventListener("click", pauseAdsForForm, true);
  }

  window.__ffLoadPop = loadPopunder;
  window.__ffSmart = fireSmart;
})();


